import Navbar from "../../UI/Navbar/Navbar";
import Footer from "../../UI/Footer/Footer";
import img1 from "../../../assets/charity_walk.png";
import img2 from "../../../assets/cook-off.png";
import img3 from "../../../assets/talent.png";
import React, { useState, useMemo, useEffect } from 'react';


useEffect(() => {
  setLoading(true);
  setFadeIn(false);

  const timer = setTimeout(() => {
    setLoading(false);
    setFadeIn(true);
  }, 300); // 300ms animation delay

  return () => clearTimeout(timer);
}, [categoryFilter, page]); 

const filteredEvents = useMemo(() => {
  if (categoryFilter === "All") return events;
  return events.filter((event) => event.type === categoryFilter);
}, [events, categoryFilter]);

const totalPages = Math.ceil(filteredEvents.length / ITEMS_PER_PAGE);

const pagedEvents = useMemo(() => {
  const start = (page - 1) * ITEMS_PER_PAGE;
  return filteredEvents.slice(start, start + ITEMS_PER_PAGE);
}, [filteredEvents, page]);

useEffect(() => {
  setPage(1);
}, [categoryFilter]);

{loading ? (
  <div className="text-center py-20 text-gray-500">Loading...</div>
) : (
  <div
    className={`grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6 transition-opacity duration-500 ${
      fadeIn ? 'opacity-100' : 'opacity-0'
    }`}
  >
    {pagedEvents.map((event, index) => (
      <div key={index} className="rounded-lg shadow bg-white overflow-hidden">
        <img src={event.image} alt={event.title} className="w-full h-48 object-cover" />
        <div className="p-4">
          <h3 className="font-semibold">{event.title}</h3>
          <p className="text-sm text-gray-600">{event.photoCount || 'no. of photos'}</p>
        </div>
      </div>
    ))}
  </div>
)}




